from pathlib import Path
import csv
rows=[]
def add(n,kind,specific,confidence,impl,contract,rationale):
 item=f'W{n:02}'
 def loc(side,entries):
  result=[]
  for name,line in entries:
   paths=[p for p in (Path(item)/side).rglob(name) if p.is_file()]
   assert len(paths)==1,(item,side,name)
   p=paths[0]
   assert 1<=line<=len(p.read_text().splitlines())
   result.append(str(p)+(':' if side=='impl' else '#L')+str(line))
  return ';'.join(result)
 rows.append(dict(item_id=item,divergence_kind=kind,contract_specificity=specific,confidence=confidence,impl_locators=loc('impl',impl),contract_locators=loc('contract',contract),rationale='⚠️ '+rationale))
